(function() {
    function quickSyncBadge() {
        try {
            var count = null;
            var match = document.cookie.match(/woocommerce_items_in_cart=([0-9]+)/);
            if (match) {
                count = parseInt(match[1], 10);
            }
            if (count === null || isNaN(count)) {
                var cached = sessionStorage.getItem('emdief_cart_data');
                if (cached) {
                    var parsed = JSON.parse(cached);
                    if (parsed && parsed.count !== undefined) {
                        count = parseInt(parsed.count, 10);
                    }
                }
            }
            if (count !== null && !isNaN(count)) {
                var b1 = document.getElementById('emdief-cart-count');
                if (b1) b1.textContent = count;
                var b2 = document.getElementById('emdief-bottom-cart-count');
                if (b2) b2.textContent = count;
                var b3 = document.getElementById('emdief-drawer-count-badge');
                if (b3) b3.textContent = count + ' ürün';
            }
        } catch (e) {}
    }
    quickSyncBadge();
    var lastConfettiTime = 0;
    function launchCartConfetti(container) {
        var now = Date.now();
        if (now - lastConfettiTime < 5000) {
            return; // 5 saniye içinde tekrar tetikleme
        }
        lastConfettiTime = now;
        var parent = container || document.querySelector('.emdief-drawer-panel') || document.body;
        if (!parent) return;
        var canvas = document.createElement('canvas');
        canvas.className = 'mis360-cart-confetti-canvas';
        canvas.style.position = 'absolute';
        canvas.style.top = '0';
        canvas.style.left = '0';
        canvas.style.width = '100%';
        canvas.style.height = '100%';
        canvas.style.pointerEvents = 'none';
        canvas.style.zIndex = '99999';
        var computedStyle = window.getComputedStyle(parent);
        if (computedStyle.position === 'static') {
            parent.style.position = 'relative';
        }
        parent.appendChild(canvas);
        var rect = parent.getBoundingClientRect();
        var width = rect.width || window.innerWidth;
        var height = rect.height || window.innerHeight;
        var dpr = window.devicePixelRatio || 1;
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        var ctx = canvas.getContext('2d');
        if (!ctx) return;
        ctx.scale(dpr, dpr);
        var colors = [
            '#f59e0b', // Güneş Sarısı
            '#10b981', // Nane Yeşili
            '#0284c7', // Gökyüzü Mavisi
            '#ff6b6b', // Mercan Pembesi
            '#8b5cf6', // Lavanta Moru
            '#ec4899', // Pembe
            '#14b8a6', // Turkuaz
            '#fbbf24'  // Altın
        ];
        var particles = [];
        var particleCount = Math.min(80, Math.max(50, Math.floor(width / 5)));
        var originX = width / 2;
        var originY = Math.min(190, height * 0.28);
        for (var i = 0; i < particleCount; i++) {
            var angle = (Math.PI * 2) * (i / particleCount) + (Math.random() - 0.5);
            var speed = 3.5 + Math.random() * 6.5;
            particles.push({
                x: originX + (Math.random() - 0.5) * 60,
                y: originY + (Math.random() - 0.5) * 30,
                vx: Math.cos(angle) * speed + (Math.random() - 0.5) * 2,
                vy: Math.sin(angle) * speed - (3 + Math.random() * 4.5),
                size: 5 + Math.random() * 6,
                color: colors[Math.floor(Math.random() * colors.length)],
                rotation: Math.random() * 360,
                rotationSpeed: (Math.random() - 0.5) * 12,
                wobble: Math.random() * 10,
                wobbleSpeed: 0.08 + Math.random() * 0.07,
                shape: Math.random() > 0.35 ? 'rect' : 'circle',
                opacity: 1,
                decay: 0.007 + Math.random() * 0.006
            });
        }
        var startTime = performance.now();
        var maxDuration = 3200;
        function renderConfetti(nowTime) {
            var elapsed = nowTime - startTime;
            if (elapsed > maxDuration || particles.length === 0) {
                if (canvas.parentNode) {
                    canvas.parentNode.removeChild(canvas);
                }
                return;
            }
            ctx.clearRect(0, 0, width, height);
            for (var j = particles.length - 1; j >= 0; j--) {
                var p = particles[j];
                p.x += p.vx;
                p.y += p.vy;
                p.vy += 0.22; // Yer çekimi
                p.vx *= 0.98; // Hava direnci
                p.vy *= 0.98;
                p.rotation += p.rotationSpeed;
                p.wobble += p.wobbleSpeed;
                p.opacity -= p.decay;
                if (p.opacity <= 0 || p.y > height + 20) {
                    particles.splice(j, 1);
                    continue;
                }
                ctx.save();
                ctx.translate(p.x, p.y);
                ctx.rotate((p.rotation * Math.PI) / 180);
                ctx.globalAlpha = Math.max(0, p.opacity);
                ctx.fillStyle = p.color;
                var scaleX = Math.cos(p.wobble);
                if (p.shape === 'rect') {
                    ctx.fillRect(-p.size * scaleX / 2, -p.size / 2, p.size * scaleX, p.size * 0.65);
                } else {
                    ctx.beginPath();
                    ctx.arc(0, 0, (p.size / 2) * Math.abs(scaleX), 0, Math.PI * 2);
                    ctx.fill();
                }
                ctx.restore();
            }
            requestAnimationFrame(renderConfetti);
        }
        requestAnimationFrame(renderConfetti);
    }
    window.mis360LaunchConfetti = launchCartConfetti;
    function initMis360CartEngine() {
        const cartDrawer    = document.getElementById('emdief-cart-drawer');
        const cartTrigger   = document.getElementById('emdief-cart-trigger');
        const cartClose     = document.getElementById('emdief-cart-close');
        const cartOverlay   = document.getElementById('emdief-cart-overlay');
        const bottomNavCart = document.getElementById('bottomNavCartBtn');
        function openCartDrawer() {
            if (!cartDrawer) return;
            const mobileDrawer = document.getElementById('emdief-mobile-drawer');
            if (mobileDrawer && mobileDrawer.classList.contains('is-active')) {
                mobileDrawer.classList.remove('is-active');
                mobileDrawer.setAttribute('aria-hidden', 'true');
            }
            cartDrawer.classList.add('is-active');
            cartDrawer.setAttribute('aria-hidden', 'false');
            document.body.style.overflow = 'hidden';
            const drawerBody = document.getElementById('emdief-drawer-cart-content');
            const match = document.cookie.match(/woocommerce_items_in_cart=([0-9]+)/);
            const cookieCount = match ? parseInt(match[1], 10) : 0;
            if (cookieCount > 0 && drawerBody && (drawerBody.querySelector('.emdief-cart-empty') || !drawerBody.children.length)) {
                if (typeof window.mis360SyncCartState === 'function') {
                    window.mis360SyncCartState();
                }
            }
            if (typeof window.mis360UnblockDrawerCart === 'function') {
                window.mis360UnblockDrawerCart();
            }
            setTimeout(function() {
                if (cartDrawer.querySelector('.mascot-speech-bubble-box.is-free-shipping')) {
                    launchCartConfetti(cartDrawer.querySelector('.emdief-drawer-panel'));
                }
            }, 300);
        }
        function closeCartDrawer() {
            if (!cartDrawer) return;
            cartDrawer.classList.remove('is-active');
            cartDrawer.setAttribute('aria-hidden', 'true');
            document.body.style.overflow = '';
        }
        window.mis360OpenCartDrawer = openCartDrawer;
        window.mis360CloseCartDrawer = closeCartDrawer;
        if (cartTrigger) {
            cartTrigger.addEventListener('click', (e) => {
                e.preventDefault();
                openCartDrawer();
            });
        }
        if (bottomNavCart) {
            bottomNavCart.addEventListener('click', (e) => {
                e.preventDefault();
                openCartDrawer();
            });
        }
        if (cartClose) {
            cartClose.addEventListener('click', (e) => {
                e.preventDefault();
                closeCartDrawer();
            });
        }
        if (cartOverlay) {
            cartOverlay.addEventListener('click', closeCartDrawer);
        }
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape') {
                closeCartDrawer();
            }
        });
        document.addEventListener('click', (e) => {
            const link = e.target.closest('a');
            if (!link) return;
            if (link.classList.contains('remove-cart-item') ||
                link.closest('.remove-cart-item') ||
                link.id === 'emdief-cart-trigger' ||
                link.id === 'bottomNavCartBtn' ||
                link.classList.contains('add_to_cart_button') ||
                link.classList.contains('trendyol-btn-add-cart') ||
                link.classList.contains('emdief-btn-add-cart') ||
                link.getAttribute('role') === 'button') {
                return;
            }
            const href = link.getAttribute('href');
            if (!href || href.startsWith('#') || href.startsWith('javascript:')) {
                return;
            }
            closeCartDrawer();
        }, { passive: true });
        if (window.jQuery) {
            const $ = window.jQuery;
            const ajaxUrl   = (window.mis360Data && window.mis360Data.ajaxUrl) ? window.mis360Data.ajaxUrl : '/wp-admin/admin-ajax.php';
            const nonce     = (window.mis360Data && window.mis360Data.nonce) ? window.mis360Data.nonce : '';
            const addedText = (window.mis360Data && window.mis360Data.addedToCartText) ? window.mis360Data.addedToCartText : '✓ Sepete Eklendi!';
            if (typeof wc_add_to_cart_params !== 'undefined') {
                wc_add_to_cart_params.cart_redirect_after_add = 'no';
            }
            function unblockDrawerCart() {
                const $drawer = $('#emdief-drawer-cart-content');
                if ($drawer.length) {
                    $drawer.stop(true, true)
                           .removeClass('updating loading processing')
                           .css({
                               'opacity': '1',
                               'pointer-events': 'auto',
                               'filter': 'none',
                               '-webkit-filter': 'none'
                           });
                    if (typeof $drawer.unblock === 'function') {
                        $drawer.unblock();
                    }
                    $drawer.find('.blockUI, .blockOverlay, .blockElement').remove();
                }
                const $panel = $('.emdief-drawer-panel');
                if ($panel.length) {
                    $panel.stop(true, true).css({ 'opacity': '1', 'filter': 'none' });
                    if (typeof $panel.unblock === 'function') {
                        $panel.unblock();
                    }
                    $panel.find('.blockUI, .blockOverlay, .blockElement').remove();
                }
                $('#emdief-cart-drawer').find('.blockUI, .blockOverlay, .blockElement').remove();
            }
            window.mis360UnblockDrawerCart = unblockDrawerCart;
            function applyFragments(data) {
                if (!data) return;
                if (data.fragments) {
                    $.each(data.fragments, function(selector, html) {
                        const $target = $(selector);
                        if ($target.length) {
                            $target.replaceWith(html);
                        }
                    });
                }
                if (data.count !== undefined) {
                    $('#emdief-cart-count').text(data.count);
                    $('#emdief-bottom-cart-count').text(data.count);
                    $('#emdief-drawer-count-badge').text(data.count + ' ürün');
                }
                if (data.subtotal !== undefined) {
                    $('.emdief-cart-total').html(data.subtotal);
                }
                unblockDrawerCart();
                setTimeout(unblockDrawerCart, 50);
                setTimeout(unblockDrawerCart, 450);
                setTimeout(function() {
                    const $freeBox = $('.mascot-speech-bubble-box.is-free-shipping');
                    if ($freeBox.length) {
                        const panel = document.querySelector('.emdief-drawer-panel') || $freeBox[0];
                        launchCartConfetti(panel);
                    }
                }, 350);
                try {
                    sessionStorage.setItem('emdief_cart_data', JSON.stringify(data));
                } catch(err) {}
            }
            function syncCartState() {
                quickSyncBadge();
                try {
                    const cachedData = sessionStorage.getItem('emdief_cart_data');
                    if (cachedData) {
                        const parsed = JSON.parse(cachedData);
                        applyFragments(parsed);
                    }
                } catch (err) {}
                $.ajax({
                    type: 'POST',
                    url: ajaxUrl,
                    data: {
                        action: 'mis360_get_cart_fragments',
                        nonce: nonce
                    },
                    success: function(response) {
                        if (response && response.success && response.data) {
                            applyFragments(response.data);
                        }
                    }
                });
            }
            window.mis360SyncCartState = syncCartState;
            syncCartState();
            window.addEventListener('pageshow', () => syncCartState());
            document.addEventListener('visibilitychange', () => {
                if (document.visibilityState === 'visible') syncCartState();
            });
            window.addEventListener('focus', () => syncCartState());
            window.addEventListener('storage', (e) => {
                if (e.key === 'emdief_cart_data') syncCartState();
            });
            $(document.body).on('added_to_cart removed_from_cart wc_fragments_refreshed wc_fragments_loaded wc_fragment_refresh', function(e, fragments) {
                if (fragments) {
                    applyFragments({ fragments: fragments });
                }
                unblockDrawerCart();
                setTimeout(unblockDrawerCart, 50);
                setTimeout(unblockDrawerCart, 450);
                syncCartState();
            });
            $(document).ajaxComplete(function(e, xhr, settings) {
                if (settings && settings.url && (settings.url.indexOf('wc-ajax=') !== -1 || settings.url.indexOf('admin-ajax.php') !== -1)) {
                    unblockDrawerCart();
                    setTimeout(unblockDrawerCart, 100);
                }
            });
            $(document).on('click', '.trendyol-btn-add-cart, .emdief-btn-add-cart, .ajax_add_to_cart', function(e) {
                e.preventDefault();
                e.stopImmediatePropagation();
                const $btn = $(this);
                if ($btn.hasClass('product_type_variable') || $btn.hasClass('product_type_grouped') || $btn.hasClass('product_type_external')) {
                    const dest = $btn.data('product_url') || $btn.attr('href');
                    if (dest && dest !== '#' && !dest.startsWith('javascript:')) {
                        window.location.href = dest;
                    }
                    return false;
                }
                if ($btn.hasClass('loading')) {
                    return false;
                }
                let productId = $btn.data('product_id') || $btn.attr('data-product_id');
                if (!productId) {
                    const href = $btn.attr('href') || '';
                    const match = href.match(/add-to-cart=([0-9]+)/);
                    if (match) productId = match[1];
                }
                if (!productId) return false;
                const qty = $btn.data('quantity') || 1;
                const originalHtml = $btn.html();
                $btn.addClass('loading').css('pointer-events', 'none');
                const $span = $btn.find('span');
                if ($span.length) {
                    $span.text('Ekleniyor...');
                }
                $.ajax({
                    type: 'POST',
                    url: ajaxUrl,
                    data: {
                        action: 'mis360_ajax_add_to_cart',
                        product_id: productId,
                        quantity: qty,
                        nonce: nonce
                    },
                    success: function(response) {
                        $btn.removeClass('loading').css('pointer-events', '');
                        if (response && response.success && response.data) {
                            applyFragments(response.data);
                            $btn.addClass('is-added');
                            if ($span.length) {
                                $span.text(addedText);
                            }
                            openCartDrawer();
                            unblockDrawerCart();
                            setTimeout(unblockDrawerCart, 100);
                            setTimeout(unblockDrawerCart, 500);
                            $(document.body).trigger('added_to_cart', [response.data.fragments, response.data.cart_hash]);
                            $(document.body).trigger('wc_fragment_refresh');
                            setTimeout(() => {
                                $btn.removeClass('is-added');
                                $btn.html(originalHtml);
                            }, 2200);
                        } else {
                            $btn.html(originalHtml);
                            const msg = (response && response.data && response.data.message) ? response.data.message : 'Ürün sepete eklenemedi.';
                            console.warn('[mis360-mobilya] Sepete ekleme:', msg);
                        }
                    },
                    error: function(xhr, status, error) {
                        $btn.removeClass('loading').css('pointer-events', '').html(originalHtml);
                        console.error('[mis360-mobilya] AJAX Hatası:', status, error);
                    }
                });
                return false;
            });
            $(document).on('click', '.remove-cart-item, a.remove', function(e) {
                e.preventDefault();
                e.stopImmediatePropagation();
                const $btn = $(this);
                const cartItemKey = $btn.data('cart_item_key') || $btn.attr('data-cart_item_key');
                if (!cartItemKey) return false;
                const $itemRow = $btn.closest('.emdief-cart-item, .cart-item-row');
                if ($itemRow.length) {
                    $itemRow.css({ opacity: '0.4', 'pointer-events': 'none' });
                }
                $.ajax({
                    type: 'POST',
                    url: ajaxUrl,
                    data: {
                        action: 'mis360_ajax_remove_cart_item',
                        cart_item_key: cartItemKey,
                        nonce: nonce
                    },
                    success: function(response) {
                        if (response && response.success && response.data) {
                            applyFragments(response.data);
                            unblockDrawerCart();
                            setTimeout(unblockDrawerCart, 100);
                            setTimeout(unblockDrawerCart, 500);
                            $(document.body).trigger('removed_from_cart', [response.data.fragments, response.data.cart_hash]);
                            $(document.body).trigger('wc_fragment_refresh');
                        } else if ($itemRow.length) {
                            $itemRow.css({ opacity: '', 'pointer-events': '' });
                            unblockDrawerCart();
                        }
                    },
                    error: function() {
                        if ($itemRow.length) {
                            $itemRow.css({ opacity: '', 'pointer-events': '' });
                        }
                    }
                });
                return false;
            });
            $(document).on('click', '.emdief-empty-cart-trigger', function(e) {
                e.preventDefault();
                e.stopImmediatePropagation();
                if (!window.confirm('Sepetinizdeki tüm ürünler silinecek. Onaylıyor musunuz?')) {
                    return false;
                }
                const $btn = $(this);
                const originalHtml = $btn.html();
                $btn.addClass('loading').css('pointer-events', 'none');
                if ($btn.find('span').length) {
                    $btn.find('span').text('Boşaltılıyor...');
                }
                const isCartPage = document.body.classList.contains('woocommerce-cart') || window.location.pathname.indexOf('/sepet') !== -1;
                const $drawer = $('#emdief-drawer-cart-content');
                if ($drawer.length) {
                    $drawer.css({ opacity: '0.4', 'pointer-events': 'none' });
                }
                $.ajax({
                    type: 'POST',
                    url: ajaxUrl,
                    data: {
                        action: 'mis360_ajax_empty_cart',
                        nonce: nonce
                    },
                    success: function(response) {
                        $btn.removeClass('loading').css('pointer-events', '').html(originalHtml);
                        if (response && response.success && response.data) {
                            applyFragments(response.data);
                            unblockDrawerCart();
                            setTimeout(unblockDrawerCart, 100);
                            setTimeout(unblockDrawerCart, 500);
                            $(document.body).trigger('removed_from_cart', [response.data.fragments, response.data.cart_hash]);
                            $(document.body).trigger('wc_fragment_refresh');
                            if (isCartPage) {
                                window.location.reload();
                            }
                        } else {
                            unblockDrawerCart();
                            if (isCartPage) {
                                window.location.reload();
                            }
                        }
                    },
                    error: function() {
                        $btn.removeClass('loading').css('pointer-events', '').html(originalHtml);
                        unblockDrawerCart();
                        if (isCartPage) {
                            window.location.reload();
                        }
                    }
                });
                return false;
            });
        }
    }
    function runInit() {
        initMis360CartEngine();
        setTimeout(function() {
            var cartPageBox = document.querySelector('.cart-page-mascot-box.is-free-shipping');
            if (cartPageBox) {
                launchCartConfetti(cartPageBox);
            }
        }, 500);
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', runInit);
    } else {
        runInit();
    }
})();